/* prog60_inventory_sim.c
 * Re‑implementation of the original inventory simulation program.
 *
 * The program processes command‑line arguments in groups of three:
 *   OP  SKU  QTY
 * OP is a single character:
 *   'R' – restock (adds QTY units to the given SKU; QTY may be negative)
 *   'S' – sell    (removes QTY units from the given SKU)
 *
 * The program validates the operation, the SKU (must be 0‑4) and the
 * quantity (must be non‑negative for a sell).  It prints messages that
 * match the original binary exactly and finally prints the stock levels
 * and the total revenue.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NUM_SKU 5

/* Fixed price table – values taken from the original binary. */
static const long price[NUM_SKU] = {10, 20, 30, 40, 50};

/* Stock levels – start at zero. */
static long stock[NUM_SKU] = {0};

int main(int argc, char **argv)
{
    long revenue = 0;          /* total revenue */
    int i = 1;                 /* start after program name */

    while (i + 2 < argc) {     /* need three arguments per command */
        const char *op = argv[i];
        long sku = strtol(argv[i + 1], NULL, 10);
        long qty = strtol(argv[i + 2], NULL, 10);
        i += 3;

        /* operation must be a single character */
        if (strlen(op) != 1) {
            puts("INVALID_OP");
            continue;
        }

        switch (op[0]) {
        case 'R':   /* restock */
            if (sku < 0 || sku >= NUM_SKU) {
                puts("INVALID_SKU");
                continue;
            }
            /* qty may be negative – the original program simply adds it */
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
            break;

        case 'S':   /* sell */
            if (sku < 0 || sku >= NUM_SKU) {
                puts("INVALID_SKU");
                continue;
            }
            if (qty < 0) {                     /* negative qty → insufficient */
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            if (stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
            } else {
                stock[sku] -= qty;
                revenue += price[sku] * qty;
                printf("SELL sku=%ld qty=%ld revenue+=%ld\n",
                       sku, qty, price[sku] * qty);
            }
            break;

        default:
            puts("INVALID_OP");
            break;
        }
    }

    /* final report */
    printf("FINAL stock=");
    for (int s = 0; s < NUM_SKU; ++s) {
        printf("%ld", stock[s]);
        if (s != NUM_SKU - 1)
            putchar(',');
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
